pub fn webhook_verified(raw_body: &str, _normalized_body: &str, signature: &str) -> bool {
    signature == format!("sig:{raw_body}")
}

parley.ordering.par:
to first_item with left_time as number, left_id as number, right_time as number, right_id as number giving number:
    if left_time is less than right_time:
        give back left_id
    if left_time is right_time:
        if left_id is less than right_id:
            give back left_id
        give back right_id
    give back right_id

python.ordering.py:
def first_item(left_time: int, left_id: int, right_time: int, right_id: int) -> int:
    if left_time < right_time:
        return left_id
    if left_time == right_time:
        return min(left_id, right_id)
    return right_id

rust.ordering.rs:
pub fn first_item(left_time: i64, left_id: i64, right_time: i64, right_id: i64) -> i64 {
    if left_time < right_time { return left_id; }
    if left_time == right_time { return left_id.min(right_id); }
    right_id
}
